fast_pseudocode:
# CORRECT: grid adapts to autotuned XBLOCK
@triton.autotune(configs=[Config({'XBLOCK': 512}, num_warps=8), ...], key=['xnumel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr): ...

grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # CORRECT
kernel[grid](..., xnumel)  # XBLOCK injected by autotune

